(*
================================================================================
FUNCTION_BLOCK FB_AutoclaveCuringSequencer
--------------------------------------------------------------------------------
VERSION: 1.0.0
DESCRIPTION:
Aerospace-grade composite autoclave curing profile sequencer. 
Implements multi-zone thermocouple averaging, nitrogen pressurization 
ramps, exothermic reaction detection (runaway temperature alarms), 
and rigorous safety interlocks (e-stops, thermal overloads).
HARDWARE ABSTRACTION: Maps raw IO signals to engineering units.
================================================================================
*)
FUNCTION_BLOCK FB_AutoclaveCuringSequencer
VAR_INPUT
    // Hardware Abstraction Layer - Raw Inputs
    bEStop_OK           : BOOL;  // TRUE = E-Stop healthy (NC contact)
    bThermalOverload_OK : BOOL;  // TRUE = Heater overload relay healthy
    bDoorLocked         : BOOL;  // TRUE = Autoclave door physically locked
    bNitrogenSupply_OK  : BOOL;  // TRUE = Nitrogen pressure at source is sufficient

    // Analog Inputs (Raw values from hardware, e.g., 0-32767 for 4-20mA)
    rZone1_Temp_Raw     : REAL;  // Zone 1 Thermocouple (deg C)
    rZone2_Temp_Raw     : REAL;  // Zone 2 Thermocouple (deg C)
    rZone3_Temp_Raw     : REAL;  // Zone 3 Thermocouple (deg C)
    rChamberPress_Raw   : REAL;  // Chamber Pressure (bar)

    // Command Inputs
    bStartCure          : BOOL;  // Trigger to start profile
    bAbort              : BOOL;  // Manual abort

    // Recipe Parameters
    rTargetTemp         : REAL;  // Target Curing Temperature (deg C)
    rTempRampRate       : REAL;  // Target Temp Ramp Rate (deg C / min)
    rTargetPress        : REAL;  // Target N2 Pressure (bar)
    rPressRampRate      : REAL;  // Target Press Ramp Rate (bar / min)
    tCureDwellTime      : TIME;  // Dwell time at target temperature
END_VAR

VAR_OUTPUT
    // Hardware Abstraction Layer - Raw Outputs
    bHeaterEnable       : BOOL;  // Energize Main Heaters
    rHeaterControlOut   : REAL;  // 0-100% Heater Output (PID)
    bNitrogenValveEnable: BOOL;  // Energize N2 Valve Solenoid
    rNitrogenControlOut : REAL;  // 0-100% N2 Proportional Valve
    bVentValve          : BOOL;  // Open Chamber Vent Valve
    bCoolingFanEnable   : BOOL;  // Energize Cooling Fan

    // Status & Alarms
    nState              : INT;   // Current sequencer state
    bSystemSafe         : BOOL;  // Interlocks OK
    bExothermAlarm      : BOOL;  // Exothermic runaway detected
    bEStopAlarm         : BOOL;  // E-Stop pressed
    bCureComplete       : BOOL;  // Curing cycle finished
END_VAR

VAR
    // Internal Variables
    rAvgTemp            : REAL;
    rAvgTempOld         : REAL;
    rTempRateOfChange   : REAL;
    rCurrentTempSetpoint: REAL;
    rCurrentPressSetpoint:REAL;

    fbTimerDwell        : TON;
    fbTimerExothermCheck: TON;

    // PID Instances
    fbTempPID           : PID;   // Standard PID Block
    fbPressPID          : PID;   // Standard PID Block

    // Constants
    MAX_SAFE_TEMP       : REAL := 250.0; // Max allowed temp in Deg C
    MAX_SAFE_PRESS      : REAL := 15.0;  // Max allowed pressure in Bar
    EXOTHERM_THRESHOLD  : REAL := 10.0;  // Deg C / min max expected rate

    CYCLE_TIME_MS       : REAL := 100.0; // Task cycle time in ms
END_VAR

// -----------------------------------------------------------------------------
// 1. SAFETY INTERLOCKS (HARDWARE ABSTRACTION)
// -----------------------------------------------------------------------------
bSystemSafe := bEStop_OK AND bThermalOverload_OK AND bDoorLocked;
bEStopAlarm := NOT bEStop_OK;

IF NOT bSystemSafe OR bAbort OR bExothermAlarm THEN
    // Fail-safe state
    nState := 99; // Abort/Fault State
END_IF;

// -----------------------------------------------------------------------------
// 2. SENSOR AVERAGING & FILTERING
// -----------------------------------------------------------------------------
// A robust autoclave uses multiple zones to ensure uniform curing.
rAvgTemp := (rZone1_Temp_Raw + rZone2_Temp_Raw + rZone3_Temp_Raw) / 3.0;

// -----------------------------------------------------------------------------
// 3. EXOTHERMIC REACTION DETECTION
// -----------------------------------------------------------------------------
// Exothermic reaction detection evaluates the Rate of Change (RoC).
// If the temperature rises significantly faster than the heater input should allow,
// a chemical exotherm is occurring (runaway), triggering a critical alarm.
fbTimerExothermCheck(IN := NOT fbTimerExothermCheck.Q, PT := T#1S);

IF fbTimerExothermCheck.Q THEN
    rTempRateOfChange := (rAvgTemp - rAvgTempOld) * 60.0; // Deg C per minute
    rAvgTempOld := rAvgTemp;

    // Only check for runaway if we are actually heating or dwelling
    IF nState > 0 AND nState < 5 THEN
        IF rTempRateOfChange > (rTempRampRate + EXOTHERM_THRESHOLD) THEN
            bExothermAlarm := TRUE;
        END_IF;
    END_IF;
END_IF;

// -----------------------------------------------------------------------------
// 4. AUTOCLAVE CURING PROFILE SEQUENCER (STATE MACHINE)
// -----------------------------------------------------------------------------
CASE nState OF
    0:  // IDLE STATE
        bHeaterEnable        := FALSE;
        bNitrogenValveEnable := FALSE;
        bVentValve           := TRUE; // Vent open when idle for safety
        bCoolingFanEnable    := FALSE;
        rCurrentTempSetpoint := rAvgTemp;
        rCurrentPressSetpoint:= rChamberPress_Raw;

        IF bStartCure AND bSystemSafe AND bNitrogenSupply_OK THEN
            bVentValve := FALSE;
            nState := 1;
            bCureComplete := FALSE;
        END_IF;

    1:  // PRESSURIZATION RAMP
        bNitrogenValveEnable := TRUE;
        bHeaterEnable        := FALSE;
        bVentValve           := FALSE;

        // Ramp up pressure setpoint
        rCurrentPressSetpoint := rCurrentPressSetpoint + (rPressRampRate * (CYCLE_TIME_MS / 60000.0));
        IF rCurrentPressSetpoint >= rTargetPress THEN
            rCurrentPressSetpoint := rTargetPress;
            nState := 2; // Move to Heat Ramp once target pressure is reached
        END_IF;

    2:  // TEMPERATURE RAMP
        bNitrogenValveEnable := TRUE;
        bHeaterEnable        := TRUE;

        // Ramp up temperature setpoint
        rCurrentTempSetpoint := rCurrentTempSetpoint + (rTempRampRate * (CYCLE_TIME_MS / 60000.0));
        IF rCurrentTempSetpoint >= rTargetTemp THEN
            rCurrentTempSetpoint := rTargetTemp;
            nState := 3; // Move to Dwell
        END_IF;

    3:  // DWELL (CURE)
        bNitrogenValveEnable := TRUE;
        bHeaterEnable        := TRUE;

        fbTimerDwell(IN := TRUE, PT := tCureDwellTime);
        IF fbTimerDwell.Q THEN
            fbTimerDwell(IN := FALSE); // Reset timer
            nState := 4; // Move to Cooling
        END_IF;

    4:  // COOLING & DEPRESSURIZATION
        bNitrogenValveEnable := FALSE;
        bHeaterEnable        := FALSE;
        bCoolingFanEnable    := TRUE;

        // Controlled venting (slow depressurization)
        rCurrentPressSetpoint := rCurrentPressSetpoint - (rPressRampRate * (CYCLE_TIME_MS / 60000.0));
        IF rCurrentPressSetpoint <= 1.1 THEN
            rCurrentPressSetpoint := 1.0; // Atmospheric
            bVentValve := TRUE; // Full open vent
        END_IF;

        IF rAvgTemp <= 40.0 AND rChamberPress_Raw <= 1.1 THEN
            bCureComplete := TRUE;
            nState := 0; // Return to IDLE
        END_IF;

    99: // FAULT / ABORT / EMERGENCY
        bHeaterEnable        := FALSE;
        bNitrogenValveEnable := FALSE;
        bCoolingFanEnable    := TRUE; // Try to cool down immediately
        bVentValve           := TRUE; // Dump pressure
        fbTimerDwell(IN := FALSE);

        IF NOT bEStopAlarm AND NOT bExothermAlarm AND bSystemSafe AND NOT bAbort THEN
            nState := 0; // Wait for operator reset
        END_IF;

    ELSE
        nState := 99;
END_CASE;

// -----------------------------------------------------------------------------
// 5. PID LOOP EXECUTION
// -----------------------------------------------------------------------------
// Temperature PID
fbTempPID(
    ACTUAL := rAvgTemp,
    SET_POINT := rCurrentTempSetpoint,
    KP := 2.5,
    TN := 10.0, // Integral Time
    TV := 0.5,  // Derivative Time
    Y_MANUAL := 0.0,
    Y_OFFSET := 0.0,
    Y_MIN := 0.0,
    Y_MAX := 100.0,
    MANUAL := FALSE,
    RESET := (nState = 0 OR nState = 99),
    Y => rHeaterControlOut
);

// Pressure PID (Nitrogen)
fbPressPID(
    ACTUAL := rChamberPress_Raw,
    SET_POINT := rCurrentPressSetpoint,
    KP := 1.2,
    TN := 5.0,
    TV := 0.1,
    Y_MANUAL := 0.0,
    Y_OFFSET := 0.0,
    Y_MIN := 0.0,
    Y_MAX := 100.0,
    MANUAL := FALSE,
    RESET := (nState = 0 OR nState = 99),
    Y => rNitrogenControlOut
);

// Hard limits for ultimate safety overrides on outputs
IF rAvgTemp > MAX_SAFE_TEMP THEN
    bHeaterEnable := FALSE;
    rHeaterControlOut := 0.0;
END_IF;

IF rChamberPress_Raw > MAX_SAFE_PRESS THEN
    bNitrogenValveEnable := FALSE;
    rNitrogenControlOut := 0.0;
END_IF;

END_FUNCTION_BLOCK

(*
=============================================================================
  COMMERCIAL HYDROPONIC GREENHOUSE CONTROLLER
  Version: 3.2.0
  Architect: Lumina Elite Synthetic Data Architect

  Description:
  This module encapsulates the core control algorithms for a commercial-scale
  hydroponics facility. It upgrades standard analog reads into a robust
  hardware abstraction layer, computes Vapor Pressure Deficit (VPD) for
  transpiration optimization, shifts LED spectrums dynamically based on
  the plant lifecycle state, and manages precise nutrient dosing via a 
  sequenced state machine with robust safety interlocks.
=============================================================================
*)

(* --- ENUMERATIONS --- *)
TYPE E_PlantLifecycle :
(
    PLANT_INIT := 0,
    PLANT_SEEDLING := 1,
    PLANT_VEGETATIVE := 2,
    PLANT_FLOWERING := 3,
    PLANT_HARVEST := 4,
    PLANT_FAULT := 99
);
END_TYPE

TYPE E_DosingState :
(
    DOSE_IDLE := 0,
    DOSE_A := 1,
    DOSE_WAIT_A := 2,
    DOSE_B := 3,
    DOSE_WAIT_B := 4,
    DOSE_PH := 5,
    DOSE_WAIT_PH := 6,
    DOSE_MIXING := 7,
    DOSE_FAULT := 99
);
END_TYPE

(* --- HARDWARE ABSTRACTION BLOCKS --- *)

(* 
  FB_AnalogSensor
  Scales raw INT values from an ADC channel into engineering units (REAL)
  and monitors for out-of-bounds (wire break or short circuit).
*)
FUNCTION_BLOCK FB_AnalogSensor
VAR_INPUT
    RawValue    : INT;      (* Raw ADC value *)
    RawMin      : INT;      (* Minimum expected raw value (e.g. 4mA = 27648/5) *)
    RawMax      : INT;      (* Maximum expected raw value (e.g. 20mA = 27648) *)
    EngMin      : REAL;     (* Minimum engineering unit value *)
    EngMax      : REAL;     (* Maximum engineering unit value *)
END_VAR
VAR_OUTPUT
    EngValue    : REAL;     (* Scaled value *)
    WireBreak   : BOOL;     (* True if raw < RawMin - tolerance *)
    ShortCircuit: BOOL;     (* True if raw > RawMax + tolerance *)
    Valid       : BOOL;     (* True if sensor is healthy *)
END_VAR
VAR
    Tolerance   : INT := 500; 
END_VAR

    (* Fault Detection *)
    WireBreak := (RawValue < (RawMin - Tolerance));
    ShortCircuit := (RawValue > (RawMax + Tolerance));
    Valid := NOT (WireBreak OR ShortCircuit);

    (* Linear Scaling if valid *)
    IF Valid AND (RawMax > RawMin) THEN
        EngValue := EngMin + (INT_TO_REAL(RawValue - RawMin) * (EngMax - EngMin)) / INT_TO_REAL(RawMax - RawMin);
    ELSE
        EngValue := 0.0; (* Safe fallback *)
    END_IF;

END_FUNCTION_BLOCK

(* --- VAPOR PRESSURE DEFICIT (VPD) CALCULATION --- *)

(* 
  FB_Calc_VPD
  Calculates VPD (in kPa) using the Tetens equation for saturation vapor pressure.
  VPD is crucial for understanding the transpiration pull of the plants.
*)
FUNCTION_BLOCK FB_Calc_VPD
VAR_INPUT
    Temp_C      : REAL;     (* Air temperature in Celsius *)
    RH_Pct      : REAL;     (* Relative humidity in percent *)
END_VAR
VAR_OUTPUT
    VPD_kPa     : REAL;     (* Vapor Pressure Deficit in kPa *)
END_VAR
VAR
    SVP         : REAL;     (* Saturation Vapor Pressure *)
    AVP         : REAL;     (* Actual Vapor Pressure *)
END_VAR

    (* Tetens formula for SVP (kPa) *)
    SVP := 0.61078 * EXP((17.27 * Temp_C) / (Temp_C + 237.3));

    (* Actual Vapor Pressure *)
    AVP := SVP * (RH_Pct / 100.0);

    (* Deficit *)
    VPD_kPa := SVP - AVP;

END_FUNCTION_BLOCK


(* --- MAIN CONTROLLER BLOCK --- *)

FUNCTION_BLOCK FB_HydroponicController
VAR_INPUT
    (* System Inputs *)
    EnableSystem    : BOOL;
    Estop_Active    : BOOL;  (* TRUE if E-Stop is PRESSED (NC contact opened) *)
    ResetFaults     : BOOL;

    (* Pump Interlocks (Thermal Overloads, NC = TRUE when healthy) *)
    Overload_PumpA  : BOOL;
    Overload_PumpB  : BOOL;
    Overload_PumpPH : BOOL;

    (* Raw Sensor Data *)
    Raw_TempAir     : INT;
    Raw_Humidity    : INT;
    Raw_WaterEC     : INT;
    Raw_WaterPH     : INT;

    (* Lifecycle Setting *)
    CurrentPhase    : E_PlantLifecycle;
END_VAR
VAR_OUTPUT
    (* Actuators *)
    Cmd_PumpA       : BOOL;
    Cmd_PumpB       : BOOL;
    Cmd_PumpPHUp    : BOOL;
    Cmd_PumpPHDown  : BOOL;

    (* LED Spectrum Controls (0.0 - 100.0%) *)
    LED_Red_Pct     : REAL;
    LED_Blue_Pct    : REAL;
    LED_White_Pct   : REAL;

    (* Diagnostics *)
    SystemFault     : BOOL;
    VPD_Value       : REAL;
    ActiveDosing    : E_DosingState;
END_VAR
VAR
    (* Sensor Instances *)
    Sens_Temp       : FB_AnalogSensor;
    Sens_RH         : FB_AnalogSensor;
    Sens_EC         : FB_AnalogSensor;
    Sens_PH         : FB_AnalogSensor;

    (* VPD Calculator *)
    VPD_Calc        : FB_Calc_VPD;

    (* Dosing State Machine Timers *)
    TON_Dose        : TON;
    TON_Mix         : TON;

    (* Internal targets *)
    Target_EC       : REAL;
    Target_PH       : REAL;

    (* Fault Latches *)
    SafetyInterlock : BOOL;
END_VAR

    (* 1. SENSOR SCALING & ABSTRACTION *)
    Sens_Temp(RawValue:=Raw_TempAir, RawMin:=0, RawMax:=27648, EngMin:=-10.0, EngMax:=50.0);
    Sens_RH(RawValue:=Raw_Humidity, RawMin:=0, RawMax:=27648, EngMin:=0.0, EngMax:=100.0);
    Sens_EC(RawValue:=Raw_WaterEC, RawMin:=0, RawMax:=27648, EngMin:=0.0, EngMax:=5.0);
    Sens_PH(RawValue:=Raw_WaterPH, RawMin:=0, RawMax:=27648, EngMin:=0.0, EngMax:=14.0);

    (* 2. VPD CALCULATION *)
    VPD_Calc(Temp_C:=Sens_Temp.EngValue, RH_Pct:=Sens_RH.EngValue);
    VPD_Value := VPD_Calc.VPD_kPa;

    (* 3. SAFETY INTERLOCKS & FAULT HANDLING *)
    (* E-Stop is typically active high when pressed, or loss of signal. Assuming Estop_Active = TRUE means STOP. *)
    (* Overloads are TRUE when healthy, FALSE when tripped. *)
    IF Estop_Active OR NOT Overload_PumpA OR NOT Overload_PumpB OR NOT Overload_PumpPH THEN
        SafetyInterlock := TRUE;
    END_IF;

    IF NOT Sens_Temp.Valid OR NOT Sens_RH.Valid OR NOT Sens_EC.Valid OR NOT Sens_PH.Valid THEN
        SafetyInterlock := TRUE;
    END_IF;

    IF ResetFaults AND NOT Estop_Active AND Overload_PumpA AND Overload_PumpB AND Overload_PumpPH THEN
        SafetyInterlock := FALSE;
    END_IF;

    SystemFault := SafetyInterlock;

    (* If system is faulted or disabled, enforce safe state *)
    IF SystemFault OR NOT EnableSystem THEN
        Cmd_PumpA := FALSE;
        Cmd_PumpB := FALSE;
        Cmd_PumpPHUp := FALSE;
        Cmd_PumpPHDown := FALSE;
        LED_Red_Pct := 0.0;
        LED_Blue_Pct := 0.0;
        LED_White_Pct := 0.0;
        ActiveDosing := E_DosingState.DOSE_IDLE;
        RETURN;
    END_IF;

    (* 4. DYNAMIC LED SPECTRUM SHIFTING & TARGET SETTINGS *)
    CASE CurrentPhase OF
        E_PlantLifecycle.PLANT_SEEDLING:
            Target_EC := 0.8;
            Target_PH := 6.0;
            LED_Blue_Pct := 80.0;   (* High blue for root/leaf development *)
            LED_Red_Pct  := 20.0;
            LED_White_Pct:= 50.0;

        E_PlantLifecycle.PLANT_VEGETATIVE:
            Target_EC := 1.5;
            Target_PH := 5.8;
            LED_Blue_Pct := 60.0;
            LED_Red_Pct  := 40.0;
            LED_White_Pct:= 80.0;

        E_PlantLifecycle.PLANT_FLOWERING:
            Target_EC := 2.2;
            Target_PH := 6.2;
            LED_Blue_Pct := 30.0;
            LED_Red_Pct  := 90.0;   (* High red to stimulate flowering *)
            LED_White_Pct:= 70.0;

        E_PlantLifecycle.PLANT_HARVEST:
            Target_EC := 0.5;       (* Flush phase *)
            Target_PH := 6.0;
            LED_Blue_Pct := 40.0;
            LED_Red_Pct  := 40.0;
            LED_White_Pct:= 40.0;

        ELSE
            LED_Blue_Pct := 0.0;
            LED_Red_Pct  := 0.0;
            LED_White_Pct:= 0.0;
    END_CASE;

    (* 5. NUTRIENT DOSING STATE MACHINE *)
    (* 
       Sequential dosing is critical. Mixing A and B directly causes nutrient lockout (precipitation).
       We dose A, mix, dose B, mix, then correct pH.
    *)

    TON_Dose(IN:= (ActiveDosing = E_DosingState.DOSE_A OR ActiveDosing = E_DosingState.DOSE_B OR ActiveDosing = E_DosingState.DOSE_PH), PT:=T#5S);
    TON_Mix(IN:= (ActiveDosing = E_DosingState.DOSE_WAIT_A OR ActiveDosing = E_DosingState.DOSE_WAIT_B OR ActiveDosing = E_DosingState.DOSE_WAIT_PH), PT:=T#30S);

    CASE ActiveDosing OF
        E_DosingState.DOSE_IDLE:
            Cmd_PumpA := FALSE; Cmd_PumpB := FALSE; Cmd_PumpPHUp := FALSE; Cmd_PumpPHDown := FALSE;
            (* Check if EC is below target by deadband *)
            IF Sens_EC.EngValue < (Target_EC - 0.1) THEN
                ActiveDosing := E_DosingState.DOSE_A;
            ELSIF Sens_PH.EngValue < (Target_PH - 0.2) OR Sens_PH.EngValue > (Target_PH + 0.2) THEN
                ActiveDosing := E_DosingState.DOSE_PH;
            END_IF;

        E_DosingState.DOSE_A:
            Cmd_PumpA := TRUE;
            IF TON_Dose.Q THEN
                Cmd_PumpA := FALSE;
                ActiveDosing := E_DosingState.DOSE_WAIT_A;
            END_IF;

        E_DosingState.DOSE_WAIT_A:
            (* Wait for circulation *)
            IF TON_Mix.Q THEN
                ActiveDosing := E_DosingState.DOSE_B;
            END_IF;

        E_DosingState.DOSE_B:
            Cmd_PumpB := TRUE;
            IF TON_Dose.Q THEN
                Cmd_PumpB := FALSE;
                ActiveDosing := E_DosingState.DOSE_WAIT_B;
            END_IF;

        E_DosingState.DOSE_WAIT_B:
            IF TON_Mix.Q THEN
                ActiveDosing := E_DosingState.DOSE_IDLE; (* Re-evaluate after mixing *)
            END_IF;

        E_DosingState.DOSE_PH:
            IF Sens_PH.EngValue > (Target_PH + 0.2) THEN
                Cmd_PumpPHDown := TRUE;
                Cmd_PumpPHUp := FALSE;
            ELSIF Sens_PH.EngValue < (Target_PH - 0.2) THEN
                Cmd_PumpPHUp := TRUE;
                Cmd_PumpPHDown := FALSE;
            END_IF;

            IF TON_Dose.Q THEN
                Cmd_PumpPHDown := FALSE;
                Cmd_PumpPHUp := FALSE;
                ActiveDosing := E_DosingState.DOSE_WAIT_PH;
            END_IF;

        E_DosingState.DOSE_WAIT_PH:
            IF TON_Mix.Q THEN
                ActiveDosing := E_DosingState.DOSE_IDLE;
            END_IF;

        ELSE
            ActiveDosing := E_DosingState.DOSE_IDLE;
    END_CASE;

END_FUNCTION_BLOCK

FUNCTION_BLOCK "FB_Coaster_Block_Zone_SIL4"
TITLE = 'SIL-4 Roller Coaster Block Zone Controller'
AUTHOR : 'Lumina Elite'
VERSION : '3.0'
// -----------------------------------------------------------------------------
// DESCRIPTION:
// SIL-4 compliant Block Zone Controller for Theme Park Roller Coasters.
// Incorporates redundant wheel-sensor tracking, anti-rollback monitoring,
// and fail-safe magnetic brake deployment. 
// Uses a complex state machine for block occupancy and train progression.
// -----------------------------------------------------------------------------

VAR_INPUT
    xEnable : BOOL; // System enable
    xEStop_Ch1 : BOOL; // E-Stop Channel 1 (Normally Closed)
    xEStop_Ch2 : BOOL; // E-Stop Channel 2 (Normally Closed)
    xReset_SIL : BOOL; // Safety Reset

    // Redundant Wheel Sensors (Train Entry)
    xWheelSens_Entry_A : BOOL;
    xWheelSens_Entry_B : BOOL;

    // Redundant Wheel Sensors (Train Exit)
    xWheelSens_Exit_A : BOOL;
    xWheelSens_Exit_B : BOOL;

    // Anti-Rollback Ratchet Monitoring
    xAntiRollback_Dog1 : BOOL;
    xAntiRollback_Dog2 : BOOL;

    // Previous and Next Block Status (SIL-3/4 Communication)
    xNextBlockClear : BOOL;
    xPrevBlockOccupied : BOOL;

    // Environment / Hardware interlocks
    xThermalOverload_Brake : BOOL;
    xDrivePowerOK : BOOL;
END_VAR

VAR_OUTPUT
    xBlockOccupied : BOOL; // Safe Block Occupied Status
    xDeployBrakes : BOOL; // Fail-Safe Magnetic Brake Deployment (TRUE = Apply Brakes)
    xDriveEnable : BOOL; // Enable LSM or Friction Wheels
    xAntiRollbackEngage : BOOL; // Engage Anti-Rollback mechanism
    xSystemFault : BOOL; // Fault flag
    wFaultCode : WORD; // Fault code for diagnostics
END_VAR

VAR
    // State Machine
    eBlockState : INT;
    // Constants for State Machine
    ST_INIT : INT := 0;
    ST_IDLE : INT := 10;
    ST_ENTRY_DETECT : INT := 20;
    ST_OCCUPIED : INT := 30;
    ST_DISPATCH_WAIT : INT := 40;
    ST_EXIT_DETECT : INT := 50;
    ST_FAULT : INT := 99;

    // Internal Timers
    fbSensorDiscrepancyTimer_Entry : TON;
    fbSensorDiscrepancyTimer_Exit : TON;
    fbRollbackTimer : TON;

    // Safety & Redundancy Flags
    xSafeEStop : BOOL;
    xSafeEntrySensors : BOOL;
    xSafeExitSensors : BOOL;

    // Edge Detection
    r_trig_Entry : R_TRIG;
    r_trig_Exit : R_TRIG;
END_VAR

BEGIN
    // -------------------------------------------------------------------------
    // 1. SAFETY & REDUNDANCY EVALUATION
    // -------------------------------------------------------------------------

    // Cross-check E-Stop channels
    xSafeEStop := xEStop_Ch1 AND xEStop_Ch2;
    IF (xEStop_Ch1 <> xEStop_Ch2) THEN
        wFaultCode := 16#E001; // E-Stop Discrepancy
        eBlockState := ST_FAULT;
    END_IF;

    // Sensor Discrepancy Evaluation (Entry)
    fbSensorDiscrepancyTimer_Entry(IN := (xWheelSens_Entry_A <> xWheelSens_Entry_B), PT := T#50ms);
    IF fbSensorDiscrepancyTimer_Entry.Q THEN
        wFaultCode := 16#S001; // Entry Sensor Discrepancy
        eBlockState := ST_FAULT;
    END_IF;
    xSafeEntrySensors := xWheelSens_Entry_A AND xWheelSens_Entry_B;

    // Sensor Discrepancy Evaluation (Exit)
    fbSensorDiscrepancyTimer_Exit(IN := (xWheelSens_Exit_A <> xWheelSens_Exit_B), PT := T#50ms);
    IF fbSensorDiscrepancyTimer_Exit.Q THEN
        wFaultCode := 16#S002; // Exit Sensor Discrepancy
        eBlockState := ST_FAULT;
    END_IF;
    xSafeExitSensors := xWheelSens_Exit_A AND xWheelSens_Exit_B;

    // Hardware interlocks
    IF xThermalOverload_Brake OR NOT xDrivePowerOK THEN
        wFaultCode := 16#H001; // Hardware failure
        eBlockState := ST_FAULT;
    END_IF;

    // Edge Detectors for Train Movement
    r_trig_Entry(CLK := xSafeEntrySensors);
    r_trig_Exit(CLK := xSafeExitSensors);

    // -------------------------------------------------------------------------
    // 2. BLOCK ZONE STATE MACHINE
    // -------------------------------------------------------------------------

    CASE eBlockState OF

        ST_INIT:
            // Initialization and Safety Checks
            xDeployBrakes := TRUE; // Fail-safe state
            xDriveEnable := FALSE;
            xAntiRollbackEngage := TRUE;
            xSystemFault := FALSE;
            wFaultCode := 16#0000;

            IF xSafeEStop AND xEnable AND xReset_SIL THEN
                eBlockState := ST_IDLE;
            END_IF;

        ST_IDLE:
            // Block is clear and waiting for train
            xBlockOccupied := FALSE;
            xDeployBrakes := FALSE; 
            xDriveEnable := FALSE;
            xAntiRollbackEngage := FALSE;

            IF r_trig_Entry.Q THEN
                eBlockState := ST_ENTRY_DETECT;
            END_IF;

        ST_ENTRY_DETECT:
            // Train is currently traversing entry sensors
            xBlockOccupied := TRUE;
            // Immediate Anti-Rollback engagement during entry phase to prevent back-slip
            xAntiRollbackEngage := TRUE;

            // Assume train fully entered after sensors clear or specific sequence
            IF NOT xSafeEntrySensors THEN
                eBlockState := ST_OCCUPIED;
            END_IF;

        ST_OCCUPIED:
            // Train fully inside the block
            xBlockOccupied := TRUE;
            xAntiRollbackEngage := TRUE;

            // Determine if it is safe to proceed
            IF xNextBlockClear THEN
                xDeployBrakes := FALSE;
                eBlockState := ST_DISPATCH_WAIT;
            ELSE
                // Block violation ahead, immediately deploy fail-safe magnetic brakes
                xDeployBrakes := TRUE; 
                xDriveEnable := FALSE;
            END_IF;

        ST_DISPATCH_WAIT:
            xBlockOccupied := TRUE;
            xDeployBrakes := FALSE;
            xAntiRollbackEngage := FALSE; // Release rollback for forward motion
            xDriveEnable := TRUE; // Enable LSM drives for dispatch

            // Monitor for Exit
            IF r_trig_Exit.Q THEN
                eBlockState := ST_EXIT_DETECT;
            END_IF;

            // Anti-rollback check during dispatch (if train rolls back unexpectedly)
            fbRollbackTimer(IN := xAntiRollback_Dog1 OR xAntiRollback_Dog2, PT := T#500ms);
            IF fbRollbackTimer.Q AND NOT xNextBlockClear THEN
                wFaultCode := 16#R001; // Rollback detected without clearance
                eBlockState := ST_FAULT;
            END_IF;

        ST_EXIT_DETECT:
            // Train is currently exiting the block
            xBlockOccupied := TRUE;
            xDriveEnable := FALSE; // Drive responsibility handed to next block

            IF NOT xSafeExitSensors THEN
                // Train has completely left the block
                eBlockState := ST_IDLE;
            END_IF;

        ST_FAULT:
            // Critical Fail-Safe State
            xSystemFault := TRUE;
            xDeployBrakes := TRUE; // Immediate Magnetic Brake Deployment
            xDriveEnable := FALSE;
            xAntiRollbackEngage := TRUE;
            xBlockOccupied := TRUE; // Assume occupied during fault

            IF xSafeEStop AND xReset_SIL THEN
                // Only allow reset if fault conditions are cleared
                eBlockState := ST_INIT;
            END_IF;

    END_CASE;

    // -------------------------------------------------------------------------
    // 3. GLOBAL FAIL-SAFE OVERRIDES
    // -------------------------------------------------------------------------

    IF NOT xSafeEStop OR eBlockState = ST_FAULT THEN
        xDeployBrakes := TRUE;
        xDriveEnable := FALSE;
        xAntiRollbackEngage := TRUE;
    END_IF;

END_FUNCTION_BLOCK

