    rVibrationVelocity : REAL;

    // Encoder (Absolute Position 0.0 to 100.0%)
    rActualPosition : REAL;
END_STRUCT
END_TYPE

TYPE ST_UltrasonicSensor :
STRUCT
    rRawLevel : REAL; (* Level in meters *)
    bFault : BOOL;
    bOutOfRange : BOOL;
END_STRUCT
END_TYPE

(*================================================================================*)
(* FUNCTION BLOCK: FB_RedundantLevelSensor                                        *)
(* Description: Implements 2oo3 voting logic for triple-redundant sensors       *)
(*================================================================================*)
FUNCTION_BLOCK FB_RedundantLevelSensor
VAR_INPUT
    Sensors : ARRAY[1..3] OF ST_UltrasonicSensor;
    rMaxDeviation : REAL := 0.15; (* Max allowed deviation between sensors in meters *)
END_VAR
VAR_OUTPUT
    rValidatedLevel : REAL;
    bSensorFault : ARRAY[1..3] OF BOOL;
    bSystemDegraded : BOOL; (* True if 2oo3 mode active *)
    bSystemFailure : BOOL;  (* True if < 2 sensors healthy *)
END_VAR
VAR
    ValidSensors : INT;
    rSum : REAL;
    i : INT;
END_VAR

ValidSensors := 0;
rSum := 0.0;
bSystemDegraded := FALSE;
bSystemFailure := FALSE;

FOR i := 1 TO 3 DO
    bSensorFault[i] := Sensors[i].bFault OR Sensors[i].bOutOfRange;
    IF NOT bSensorFault[i] THEN
        ValidSensors := ValidSensors + 1;
        rSum := rSum + Sensors[i].rRawLevel;
    END_IF
END_FOR;

IF ValidSensors = 3 THEN
    // Check deviation
    IF ABS(Sensors[1].rRawLevel - Sensors[2].rRawLevel) > rMaxDeviation OR
       ABS(Sensors[2].rRawLevel - Sensors[3].rRawLevel) > rMaxDeviation OR
       ABS(Sensors[1].rRawLevel - Sensors[3].rRawLevel) > rMaxDeviation THEN
        bSystemDegraded := TRUE;
        // In a real scenario, isolate the out-of-bounds sensor, for brevity, we fallback to conservative avg
        rValidatedLevel := rSum / 3.0;
    ELSE
        rValidatedLevel := rSum / 3.0;
    END_IF
ELSIF ValidSensors = 2 THEN
    bSystemDegraded := TRUE;
    rValidatedLevel := rSum / 2.0;
ELSIF ValidSensors = 1 THEN
    // Critical failure, cannot rely on 1oo3 for dam safety
    bSystemFailure := TRUE;
    rValidatedLevel := rSum; // Use last known, trigger fault
ELSE
    bSystemFailure := TRUE;
    rValidatedLevel := 0.0;
END_IF
END_FUNCTION_BLOCK


(*================================================================================*)
(* FUNCTION BLOCK: FB_WatershedPredictor                                          *)
(* Description: Predicts future level based on ROC and upstream telemetry         *)
(*================================================================================*)
FUNCTION_BLOCK FB_WatershedPredictor
VAR_INPUT
    rCurrentLevel : REAL;
    rUpstreamInflow_m3s : REAL; (* Telemetry from upstream gauge *)
    rCurrentDischarge_m3s : REAL;
    rReservoirArea_m2 : REAL := 5000000.0;
    rTimeHorizon_hr : REAL := 4.0;
END_VAR
VAR_OUTPUT
    rPredictedLevel : REAL;
    bHighLevelWarning : BOOL;
    bSpillwayTrigger : BOOL;
END_VAR
VAR
    rNetFlow : REAL;
    rVolumeChange : REAL;
    rLevelChange : REAL;
    rMaxSafeLevel : REAL := 250.0;
    rSpillLevel : REAL := 248.5;
END_VAR

// Calculate Net Flow into Reservoir (Inflow - Outflow)
rNetFlow := rUpstreamInflow_m3s - rCurrentDischarge_m3s;

// Volumetric change over prediction horizon (Net Flow * Horizon in seconds)
rVolumeChange := rNetFlow * (rTimeHorizon_hr * 3600.0);

// Predicted change in level
rLevelChange := rVolumeChange / rReservoirArea_m2;
rPredictedLevel := rCurrentLevel + rLevelChange;

bHighLevelWarning := (rPredictedLevel > rSpillLevel);
bSpillwayTrigger := (rPredictedLevel > rMaxSafeLevel) OR (rCurrentLevel > rSpillLevel);

END_FUNCTION_BLOCK


(*================================================================================*)
(* FUNCTION BLOCK: FB_TainterGate                                                 *)
(* Description: Controls a single radial gate with vibration damping              *)
(*================================================================================*)
FUNCTION_BLOCK FB_TainterGate
VAR_INPUT
    ioHW : REFERENCE TO ST_HardwareIO;
    rTargetPosition : REAL;
    rMaxLiftSpeed : REAL := 2.0; (* % per second *)
    bEnable : BOOL;
    bEmergencyOpen : BOOL;
END_VAR
VAR_OUTPUT
    eState : E_GateState;
    bAtPosition : BOOL;
    bFault : BOOL;
    bVibrationWarning : BOOL;
    rCurrentPosition : REAL;
END_VAR
VAR
    rPositionError : REAL;
    rDeadband : REAL := 0.5;
    rVibrationLimit : REAL := 15.0; (* mm/s RMS *)
    rVibrationTrip : REAL := 25.0; (* mm/s RMS *)
END_VAR

rCurrentPosition := ioHW.rActualPosition;
rPositionError := rTargetPosition - rCurrentPosition;
bAtPosition := ABS(rPositionError) <= rDeadband;
bFault := FALSE;

// Hardware Interlocks
IF NOT ioHW.bEStop_ChannelA OR NOT ioHW.bEStop_ChannelB OR ioHW.bThermalOverload THEN
    bFault := TRUE;
    eState := GATE_FAULT;
    ioHW.bCommandOpen := FALSE;
    ioHW.bCommandClose := FALSE;
    RETURN;
END_IF

// Vibration Monitoring
bVibrationWarning := ioHW.rVibrationVelocity >= rVibrationLimit;
IF ioHW.rVibrationVelocity >= rVibrationTrip THEN
    // If vibrating heavily, stop movement to prevent resonance / structural damage
    ioHW.bCommandOpen := FALSE;
    ioHW.bCommandClose := FALSE;
    eState := GATE_LOCKED;
    RETURN;
END_IF

IF NOT bEnable AND NOT bEmergencyOpen THEN
    ioHW.bCommandOpen := FALSE;
    ioHW.bCommandClose := FALSE;
    eState := GATE_HOLDING;
    RETURN;
END_IF

IF bEmergencyOpen THEN
    IF rCurrentPosition < 99.0 THEN
        ioHW.bCommandOpen := TRUE;
        ioHW.bCommandClose := FALSE;
        eState := GATE_OPENING;
    ELSE
        ioHW.bCommandOpen := FALSE;
        eState := GATE_HOLDING;
    END_IF
    RETURN;
END_IF

// Normal PID/Target Logic (Simplified Bang-Bang with Vibration Damping)
IF bAtPosition THEN
    ioHW.bCommandOpen := FALSE;
    ioHW.bCommandClose := FALSE;
    eState := GATE_HOLDING;
ELSIF rPositionError > 0.0 THEN
    // Need to open
    // If vibration warning, slow down or pause
    IF bVibrationWarning THEN
        ioHW.bCommandOpen := FALSE; // Pause lifting to let structural resonance damp out
        eState := GATE_HOLDING;
    ELSE
        ioHW.bCommandOpen := TRUE;
        ioHW.bCommandClose := FALSE;
        eState := GATE_OPENING;
    END_IF
ELSE
    // Need to close
    IF bVibrationWarning THEN
        ioHW.bCommandClose := FALSE;
        eState := GATE_HOLDING;
    ELSE
        ioHW.bCommandOpen := FALSE;
        ioHW.bCommandClose := TRUE;
        eState := GATE_CLOSING;
    END_IF
END_IF

END_FUNCTION_BLOCK


(*================================================================================*)
(* PROGRAM: PRG_SpillwayController                                                *)
(* Description: Main routine for dam spillway synchronization and execution       *)
(*================================================================================*)
PROGRAM PRG_SpillwayController
VAR
    eSystemState : E_SpillwayState := ST_INIT;

    // Sub-Systems
    fbLevelVoting : FB_RedundantLevelSensor;
    fbPredictor : FB_WatershedPredictor;
    fbGates : ARRAY[1..3] OF FB_TainterGate;

    // I/O Mapping
    hwSensors : ARRAY[1..3] OF ST_UltrasonicSensor;
    hwGates : ARRAY[1..3] OF ST_HardwareIO;

    // Global Setpoints & Telemetry
    rTargetTotalDischarge : REAL;
    rUpstreamInflow : REAL;
    rCurrentDischarge : REAL;

    bSystemFault : BOOL;
    bEmergencySpill : BOOL;
    rGlobalGateTarget : REAL;
    i : INT;
END_VAR

// 1. Process 3oo3 Redundant Level Sensors
fbLevelVoting(
    Sensors := hwSensors,
    rMaxDeviation := 0.2
);

IF fbLevelVoting.bSystemFailure THEN
    eSystemState := ST_FAULT;
    bSystemFault := TRUE;
END_IF

// 2. Predict Watershed Level and Catchment
fbPredictor(
    rCurrentLevel := fbLevelVoting.rValidatedLevel,
    rUpstreamInflow_m3s := rUpstreamInflow,
    rCurrentDischarge_m3s := rCurrentDischarge,
    rTimeHorizon_hr := 6.0
);

IF fbPredictor.bSpillwayTrigger THEN
    bEmergencySpill := TRUE;
    eSystemState := ST_EMERGENCY_DUMP;
END_IF

// 3. State Machine for Synchronous Lifting
CASE eSystemState OF
    ST_INIT:
        rGlobalGateTarget := 0.0;
        bSystemFault := FALSE;
        bEmergencySpill := FALSE;
        IF NOT bSystemFault THEN
            eSystemState := ST_IDLE;
        END_IF

    ST_IDLE:
        IF fbPredictor.bHighLevelWarning AND NOT bEmergencySpill THEN
            eSystemState := ST_CALCULATE_DISCHARGE;
        END_IF

    ST_CALCULATE_DISCHARGE:
        // PI algorithm for target position would go here.
        // Simplified: Open gates proportionally to predicted overage
        rGlobalGateTarget := (fbPredictor.rPredictedLevel - 248.5) * 10.0;
        IF rGlobalGateTarget > 100.0 THEN rGlobalGateTarget := 100.0; END_IF
        IF rGlobalGateTarget < 0.0 THEN rGlobalGateTarget := 0.0; END_IF

        eSystemState := ST_SYNCHRONOUS_LIFT;

    ST_SYNCHRONOUS_LIFT:
        // Wait for gates to reach target
        IF fbGates[1].bAtPosition AND fbGates[2].bAtPosition AND fbGates[3].bAtPosition THEN
            eSystemState := ST_HOLD_POSITION;
        END_IF

        // Return to IDLE if level stabilizes
        IF NOT fbPredictor.bHighLevelWarning THEN
            rGlobalGateTarget := 0.0;
            eSystemState := ST_SYNCHRONOUS_LOWER;
        END_IF

    ST_SYNCHRONOUS_LOWER:
        IF fbGates[1].bAtPosition AND fbGates[2].bAtPosition AND fbGates[3].bAtPosition THEN
            eSystemState := ST_IDLE;
        END_IF

    ST_HOLD_POSITION:
        IF fbPredictor.bHighLevelWarning THEN
            eSystemState := ST_CALCULATE_DISCHARGE; // Recalculate
        ELSE
            rGlobalGateTarget := 0.0;
            eSystemState := ST_SYNCHRONOUS_LOWER;
        END_IF

    ST_EMERGENCY_DUMP:
        rGlobalGateTarget := 100.0; // 100% open
        IF NOT fbPredictor.bSpillwayTrigger THEN
            bEmergencySpill := FALSE;
            eSystemState := ST_CALCULATE_DISCHARGE;
        END_IF

    ST_FAULT:
        // In fault, hold positions unless E-Dump is required
        IF bEmergencySpill THEN
            rGlobalGateTarget := 100.0;
        END_IF

END_CASE

// 4. Synchronous Execution of Tainter Gates
// Cross-couple gates: If Gate 1 is vibrating and stuck, others must adjust to prevent structural torsion.
FOR i := 1 TO 3 DO
    fbGates[i](
        ioHW := hwGates[i],
        rTargetPosition := rGlobalGateTarget,
        bEnable := (eSystemState = ST_SYNCHRONOUS_LIFT OR eSystemState = ST_SYNCHRONOUS_LOWER OR eSystemState = ST_EMERGENCY_DUMP),
        bEmergencyOpen := bEmergencySpill
    );

    // Torsional safety: Ensure gates don't deviate from each other by > 10%
    IF i > 1 THEN
        IF ABS(fbGates[i].rCurrentPosition - fbGates[i-1].rCurrentPosition) > 10.0 THEN
            // Halt the faster gate to let the slower catch up (synchronous compensation)
            // Implementation abstracted via target modifications in real system
            ;
        END_IF
    END_IF
END_FOR

END_PROGRAM

(*
    VERSION 2.0
    AUTHOR: Synthetic Data Architect

    DESCRIPTION:
    Ultra-low temperature (milli-Kelvin) He3/He4 isotope mixture regulation, 
    turbo-molecular vacuum pump sequencing, and superconducting magnet quench detection.
*)
FUNCTION_BLOCK CRYOSTAT_DR_CTRL
VAR_INPUT
    Enable : BOOL; // Main system enable
    E_Stop : BOOL; // Emergency stop, active low

    // Hardware Sensors
    T_Still : REAL; // Temperature of Still (K)
    T_MC : REAL;    // Temperature of Mixing Chamber (K)
    T_4K_Stage : REAL; // Temperature of 4K stage (K)
    P_Still : REAL; // Pressure at Still (mbar)
    P_Cond : REAL;  // Condensing pressure (mbar)
    P_OVC : REAL;   // Outer Vacuum Chamber pressure (mbar)

    // Magnet Sensors
    Mag_V_Lead : REAL; // Voltage across magnet leads (V)
    Mag_Current : REAL; // Current through magnet (A)

    // Pump Feedback
    Turbo_Speed_Hz : REAL; // Turbo pump speed in Hz
    Turbo_Fault : BOOL;    // Turbo pump internal fault
    Forepump_Fault : BOOL; // Forepump overload/fault
END_VAR

VAR_OUTPUT
    // Actuators & Pumps
    Cmd_Turbo_Run : BOOL; 
    Cmd_Forepump_Run : BOOL;
    Cmd_He3_He4_Valve : REAL; // 0-100% Flow control valve
    Cmd_Still_Heater : REAL; // 0-100% Still heater power

    // Magnet Protection
    Cmd_Dump_Resistor : BOOL; // Engage dump resistor
    Cmd_Mag_PSU_Trip : BOOL; // Trip Magnet PSU

    // Status
    Sys_State : INT; // System State Machine
    Fault_Code : DWORD; // Bitfield of faults
    MC_Temp_mK : REAL; // Mixing chamber temp in mK
END_VAR

VAR
    // State Machine Constants
    STATE_IDLE : INT := 0;
    STATE_PUMPDOWN : INT := 10;
    STATE_COOL_4K : INT := 20;
    STATE_CONDENSING : INT := 30;
    STATE_CIRCULATING : INT := 40;
    STATE_QUENCH : INT := 99;
    STATE_FAULT : INT := 100;

    // Timers
    TMR_Pumpdown : TON;
    TMR_Condensing : TON;

    // Quench Detection
    Prev_Mag_V : REAL;
    Quench_Threshold_V_s : REAL := 5.0; // V/s
    dV_dt : REAL;

    // PID for He3/He4
    PID_Mix_Err : REAL;
    PID_Mix_Integral : REAL;

    // Internal Flags
    Sys_Fault : BOOL;
END_VAR

// ==============================================================================
// 1. HARDWARE ABSTRACTION & SCALING
// ==============================================================================
MC_Temp_mK := T_MC * 1000.0; // Convert to mK for precise reporting

// ==============================================================================
// 2. SAFETY INTERLOCKS & FAULT EVALUATION
// ==============================================================================
Fault_Code := 0;
Sys_Fault := FALSE;

// Check E-Stop
IF NOT E_Stop THEN
    Fault_Code.0 := TRUE;
    Sys_Fault := TRUE;
END_IF;

// Check Pump Faults
IF Turbo_Fault THEN
    Fault_Code.1 := TRUE;
    Sys_Fault := TRUE;
END_IF;

IF Forepump_Fault THEN
    Fault_Code.2 := TRUE;
    Sys_Fault := TRUE;
END_IF;

// Vacuum interlock (OVC must be < 1e-4 mbar for operation)
IF P_OVC > 1.0E-4 AND Sys_State > STATE_PUMPDOWN THEN
    Fault_Code.3 := TRUE;
    Sys_Fault := TRUE;
END_IF;

// ==============================================================================
// 3. SUPERCONDUCTING MAGNET QUENCH DETECTION
// ==============================================================================
// Calculate derivative of voltage (assuming fixed 10ms cycle time for simplicity)
dV_dt := (Mag_V_Lead - Prev_Mag_V) * 100.0; 
Prev_Mag_V := Mag_V_Lead;

IF ABS(dV_dt) > Quench_Threshold_V_s AND Mag_Current > 10.0 THEN
    // Quench detected! Rapid energy conversion to heat.
    Fault_Code.4 := TRUE;
    Sys_State := STATE_QUENCH;
END_IF;

// ==============================================================================
// 4. MAIN STATE MACHINE
// ==============================================================================
CASE Sys_State OF
    STATE_IDLE:
        Cmd_Turbo_Run := FALSE;
        Cmd_Forepump_Run := FALSE;
        Cmd_He3_He4_Valve := 0.0;
        Cmd_Still_Heater := 0.0;

        IF Enable AND NOT Sys_Fault THEN
            Sys_State := STATE_PUMPDOWN;
        END_IF;

    STATE_PUMPDOWN:
        // Sequence: Forepump first, then Turbo
        Cmd_Forepump_Run := TRUE;
        TMR_Pumpdown(IN:=Cmd_Forepump_Run, PT:=T#5M);

        IF TMR_Pumpdown.Q THEN
            Cmd_Turbo_Run := TRUE;
        END_IF;

        // Wait for OVC pressure to drop and turbo to reach operational speed
        IF P_OVC < 1.0E-4 AND Turbo_Speed_Hz > 800.0 THEN
            Sys_State := STATE_COOL_4K;
        END_IF;

    STATE_COOL_4K:
        // Wait for Pre-cooling stage to reach liquid helium temperatures (~4K)
        IF T_4K_Stage < 4.5 THEN
            Sys_State := STATE_CONDENSING;
        END_IF;

    STATE_CONDENSING:
        // Inject He3/He4 mixture to condense into the circulation loop
        Cmd_He3_He4_Valve := 100.0; // Full open to condense

        IF P_Cond < 50.0 AND T_Still < 1.2 THEN
            Sys_State := STATE_CIRCULATING;
        END_IF;

    STATE_CIRCULATING:
        // Closed-loop PID regulation for milli-Kelvin operation
        PID_Mix_Err := 15.0 - MC_Temp_mK; // Target 15mK for qubit coherence
        PID_Mix_Integral := PID_Mix_Integral + (PID_Mix_Err * 0.01);

        // Anti-windup
        IF PID_Mix_Integral > 100.0 THEN PID_Mix_Integral := 100.0; END_IF;
        IF PID_Mix_Integral < 0.0 THEN PID_Mix_Integral := 0.0; END_IF;

        Cmd_He3_He4_Valve := (PID_Mix_Err * 0.5) + PID_Mix_Integral;
        IF Cmd_He3_He4_Valve > 100.0 THEN Cmd_He3_He4_Valve := 100.0; END_IF;
        IF Cmd_He3_He4_Valve < 0.0 THEN Cmd_He3_He4_Valve := 0.0; END_IF;

        // Still heater logic to maintain osmotic pressure gradient
        Cmd_Still_Heater := 10.0; // Base power for circulation (mW)

        IF NOT Enable THEN
            Sys_State := STATE_IDLE;
        END_IF;

    STATE_QUENCH:
        // EMERGENCY MAGNET DISCHARGE - Triggered by massive resistance increase
        Cmd_Dump_Resistor := TRUE;
        Cmd_Mag_PSU_Trip := TRUE;

        // Protect delicate cooling system components from massive heat load explosion
        Cmd_He3_He4_Valve := 0.0;
        Cmd_Still_Heater := 0.0;

        IF NOT Enable AND Mag_Current < 1.0 THEN
            Sys_State := STATE_FAULT; // Must be manually reset
        END_IF;

    STATE_FAULT:
        // Safe state
        Cmd_Turbo_Run := FALSE;
        Cmd_Forepump_Run := FALSE;
        Cmd_He3_He4_Valve := 0.0;
        Cmd_Still_Heater := 0.0;

        IF NOT Sys_Fault AND NOT Enable THEN
            Sys_State := STATE_IDLE;
        END_IF;

    ELSE
        Sys_State := STATE_FAULT;
END_CASE;

// ==============================================================================
// 5. GLOBAL FAULT OVERRIDE
// ==============================================================================
IF Sys_Fault AND Sys_State <> STATE_QUENCH THEN
    Sys_State := STATE_FAULT;
END_IF;
END_FUNCTION_BLOCK

