    xEngineRunning     : BOOL;      // Engine at idle or above
    xFaultActive       : BOOL;      // System Faulted
    iStateSequence     : INT;       // Current State Sequence
    sStateDescription  : STRING;    // Human-readable state

    // Telemetry
    rCalculatedThrustError : REAL;
END_VAR

VAR
    // State Machine
    eEngineState       : (INIT, PRELUBE, CRANKING, IGNITION, ACCELERATION, IDLE, RUNNING, COOLDOWN, SHUTDOWN, FAULTED);

    // FADEC Simulation Variables
    fbFuelPID          : FB_PID_Advanced; // (Assumed external PID block)
    rFuelPID_Out       : REAL;
    rSpoolAccelRate    : REAL;

    // Timers
    fbTimerCrank       : TON;
    fbTimerIgnition    : TON;
    fbTimerCooldown    : TON;
    fbTimerPrelube     : TON;

    // Safety & Limits
    rTIT_Limit_Max     : REAL := 1250.0;  // Absolute Max TIT (Deg C)
    rTIT_Limit_Warn    : REAL := 1150.0;
    rN2_Idle_Speed     : REAL := 15000.0; // RPM
    rOilPress_Min      : REAL := 2.5;     // Bar

    xFault_TIT_Trip    : BOOL;
    xFault_Oil_Trip    : BOOL;
    xFault_Hardware    : BOOL;
END_VAR

BEGIN
    // ==============================================================================
    //  1. SAFETY INTERLOCKS & OVER-TEMP SHUTDOWN LOGIC
    // ==============================================================================

    // Consolidate Hardware Safety
    xFault_Hardware := SafetyInterlocks.xEstopActive OR SafetyInterlocks.xFireDetect OR 
                       SafetyInterlocks.xCellDoorOpen OR SafetyInterlocks.xFuelLeak OR 
                       SafetyInterlocks.xVibrationTrip OR SafetyInterlocks.xThermalOverload OR
                       xCmdEmergencyStop;

    // Turbine Inlet Temperature (TIT) Over-Temp Logic
    IF Sensors.rTIT > rTIT_Limit_Max THEN
        xFault_TIT_Trip := TRUE;
    END_IF;

    // Oil Pressure Loss (only evaluate if engine is actually spinning up or running)
    IF eEngineState >= ACCELERATION AND eEngineState <= COOLDOWN THEN
        IF Sensors.rOilPress < rOilPress_Min THEN
            xFault_Oil_Trip := TRUE;
        END_IF;
    END_IF;

    // Trigger Fault State
    IF xFault_Hardware OR xFault_TIT_Trip OR xFault_Oil_Trip THEN
        eEngineState := FAULTED;
    END_IF;

    // ==============================================================================
    //  2. FADEC STATE MACHINE (FULL AUTHORITY DIGITAL ENGINE CONTROL)
    // ==============================================================================

    CASE eEngineState OF

        INIT:
            sStateDescription := 'Initialization and Safety Checks';
            Actuators.rFuelValveCmd := 0.0;
            Actuators.rStarterMotorCmd := 0.0;
            Actuators.xIgniterCmd := FALSE;
            Actuators.xBleedValveCmd := TRUE; // Open to prevent surge on start
            Actuators.xCoolingFanCmd := FALSE;
            xEngineRunning := FALSE;

            IF NOT xFault_Hardware AND NOT xFault_TIT_Trip THEN
                xSystemReady := TRUE;
                IF xCmdStartCycle THEN
                    xSystemReady := FALSE;
                    eEngineState := PRELUBE;
                END_IF;
            ELSE
                xSystemReady := FALSE;
            END_IF;

        PRELUBE:
            sStateDescription := 'Pre-lubrication of Engine Bearings';
            // Start external oil pumps (abstracted)
            fbTimerPrelube(IN := TRUE, PT := T#5s);
            IF fbTimerPrelube.Q THEN
                IF Sensors.rOilPress >= rOilPress_Min THEN
                    fbTimerPrelube(IN := FALSE); // Reset
                    eEngineState := CRANKING;
                ELSE
                    xFault_Oil_Trip := TRUE;
                    eEngineState := FAULTED;
                END_IF;
            END_IF;

        CRANKING:
            sStateDescription := 'Cranking N2 Spool';
            Actuators.rStarterMotorCmd := 80.0; // Engage starter
            Actuators.xCoolingFanCmd := TRUE;   // Start cell exhaust fans

            IF Sensors.rN2_Speed > 2500.0 THEN // Sufficient air flow
                eEngineState := IGNITION;
            END_IF;

        IGNITION:
            sStateDescription := 'Igniter ON and Fuel introduction';
            Actuators.xIgniterCmd := TRUE;
            Actuators.rFuelValveCmd := 5.0; // Light-off fuel schedule

            fbTimerIgnition(IN := TRUE, PT := T#3s);
            IF fbTimerIgnition.Q THEN
                // Confirm light-off by checking TIT rise
                IF Sensors.rTIT > 300.0 THEN
                    fbTimerIgnition(IN := FALSE);
                    Actuators.xIgniterCmd := FALSE;
                    eEngineState := ACCELERATION;
                ELSE
                    // Failed to light off
                    eEngineState := FAULTED;
                END_IF;
            END_IF;

        ACCELERATION:
            sStateDescription := 'Accelerating to Idle';
            // Cut starter motor gradually as engine self-sustains
            IF Sensors.rN2_Speed > 8000.0 THEN
                Actuators.rStarterMotorCmd := 0.0;
                Actuators.xBleedValveCmd := FALSE; // Close bleed valves
            END_IF;

            // Ramp fuel to idle
            Actuators.rFuelValveCmd := 10.0; // Simplified scheduling

            IF Sensors.rN2_Speed >= rN2_Idle_Speed THEN
                xEngineRunning := TRUE;
                eEngineState := IDLE;
            END_IF;

        IDLE:
            sStateDescription := 'Engine at Idle Ground State';
            Actuators.rFuelValveCmd := 12.0; // Steady state idle fuel

            IF xCmdStopCycle THEN
                eEngineState := COOLDOWN;
            ELSIF rTargetThrust > 0.0 THEN
                eEngineState := RUNNING;
            END_IF;

        RUNNING:
            sStateDescription := 'Closed-Loop Thrust Control Active';

            // Outer loop: Target Thrust -> Inner loop: Fuel Flow (using assumed PID)
            rCalculatedThrustError := rTargetThrust - Sensors.rThrust;

            fbFuelPID(
                xEnable := TRUE,
                rSetpoint := rTargetThrust,
                rProcessValue := Sensors.rThrust,
                rKp := 0.5,
                rTi := 1.2,
                rTd := 0.1,
                rOutput => rFuelPID_Out
            );

            // Apply PID to fuel valve with limits
            Actuators.rFuelValveCmd := LIMIT(MN := 10.0, IN := rFuelPID_Out, MX := 100.0);

            IF xCmdStopCycle THEN
                fbFuelPID(xEnable := FALSE);
                eEngineState := COOLDOWN;
            END_IF;

        COOLDOWN:
            sStateDescription := 'Engine Cooldown at Idle';
            xEngineRunning := FALSE;
            Actuators.rFuelValveCmd := 12.0; // Return to idle

            fbTimerCooldown(IN := TRUE, PT := T#120s);
            IF fbTimerCooldown.Q THEN
                fbTimerCooldown(IN := FALSE);
                eEngineState := SHUTDOWN;
            END_IF;

        SHUTDOWN:
            sStateDescription := 'Fuel Cutoff and Spool Down';
            Actuators.rFuelValveCmd := 0.0;

            IF Sensors.rN2_Speed < 50.0 THEN
                Actuators.xCoolingFanCmd := FALSE;
                eEngineState := INIT;
            END_IF;

        FAULTED:
            sStateDescription := 'SYSTEM FAULT - IMMEDIATE SHUTDOWN';
            xFaultActive := TRUE;
            xEngineRunning := FALSE;

            // FADEC Emergency Safing
            Actuators.rFuelValveCmd := 0.0;
            Actuators.rStarterMotorCmd := 0.0;
            Actuators.xIgniterCmd := FALSE;
            Actuators.rVectorPitchCmd := 0.0;
            Actuators.rVectorYawCmd := 0.0;

            // Keep cooling fans on if TIT is hot
            IF Sensors.rTIT > 200.0 THEN
                Actuators.xCoolingFanCmd := TRUE;
            ELSE
                Actuators.xCoolingFanCmd := FALSE;
            END_IF;

            // Reset logic
            IF NOT xFault_Hardware AND NOT xFault_TIT_Trip AND NOT xFault_Oil_Trip THEN
                // Require manual reset of software latches (simplified here)
                IF xCmdStopCycle THEN // Use stop as reset
                    xFaultActive := FALSE;
                    eEngineState := INIT;
                END_IF;
            END_IF;

    END_CASE;

    // Output state mapping
    iStateSequence := eEngineState;

    // ==============================================================================
    //  3. THRUST VECTORING CLOSED-LOOP CONTROL
    // ==============================================================================

    // Vectoring is only active when Engine is Running or at Idle
    IF (eEngineState = IDLE OR eEngineState = RUNNING) THEN
        // Simple Proportional feedback loop for Vectoring Nozzles
        // In reality, this requires complex kinematic transformations.
        // We simulate a basic P-controller with physical limits.

        Actuators.rVectorPitchCmd := rTargetVectorPitch;
        Actuators.rVectorYawCmd   := rTargetVectorYaw;

        // Clamp output commands to physical servo limits (-15 to +15 degrees)
        Actuators.rVectorPitchCmd := LIMIT(MN := -15.0, IN := Actuators.rVectorPitchCmd, MX := 15.0);
        Actuators.rVectorYawCmd   := LIMIT(MN := -15.0, IN := Actuators.rVectorYawCmd, MX := 15.0);
    ELSE
        // Return to neutral if not running
        Actuators.rVectorPitchCmd := 0.0;
        Actuators.rVectorYawCmd   := 0.0;
    END_IF;

END_FUNCTION_BLOCK
