(*
    =============================================================================
    BLOCK: ACCEL_BEAM_STEERING_CTRL
    VERSION: 3.1.0 (ENTERPRISE GRADE)
    AUTHOR: Lumina Synthetic Data Architect
    DESCRIPTION: 
    Advanced Beam Steering Controller for High-Energy Synchrotron/Linac applications.
    Implements Nano-second synchronized Quadrupole pulse shaping, ultra-fast BPM 
    (Beam Position Monitor) PID feedback loops, and critical Klystron RF interlocks.
    =============================================================================
*)
FUNCTION_BLOCK ACCEL_BEAM_STEERING_CTRL
VAR_INPUT
    Enable_Beam : BOOL;                   (* Main permissive to inject beam *)
    Clock_Pulse_NS : DINT;                (* Nano-second synchronization clock *)

    (* Beam Position Monitor (BPM) Inputs *)
    BPM_X_Pos : LREAL;                    (* Actual X position [mm] *)
    BPM_Y_Pos : LREAL;                    (* Actual Y position [mm] *)
    BPM_Intensity : LREAL;                (* Beam intensity/current [mA] *)

    (* Klystron RF Telemetry *)
    Klystron_Fwd_Pwr : LREAL;             (* Forward RF Power [kW] *)
    Klystron_Refl_Pwr : LREAL;            (* Reflected RF Power [kW] *)
    Klystron_Temp : LREAL;                (* Cavity Temperature [C] *)

    (* Steering Targets *)
    Target_X : LREAL;
    Target_Y : LREAL;
END_VAR

VAR_OUTPUT
    Quad_X_PWM : LREAL;                   (* Quadrupole X-Axis Control Duty Cycle [0-100%] *)
    Quad_Y_PWM : LREAL;                   (* Quadrupole Y-Axis Control Duty Cycle [0-100%] *)

    Klystron_Enable : BOOL;               (* RF Drive Permissive *)
    Beam_Dump_Trig : BOOL;                (* Emergency Beam Dump Activation *)

    Status_Word : WORD;                   (* System Status Flags *)
    Error_Code : DWORD;                   (* Active Fault Code *)
END_VAR

VAR
    (* Internal State Machine *)
    System_State : INT := 0;
    STATE_STANDBY : INT := 0;
    STATE_CHARGING : INT := 10;
    STATE_RF_WARMUP : INT := 20;
    STATE_ACTIVE : INT := 30;
    STATE_FAULT : INT := 99;

    (* Interlock Timers & Safety *)
    TMR_Reflect_Fault : TON;
    TMR_Thermal_Fault : TON;
    VSWR_Ratio : LREAL;

    (* BPM PID Controllers *)
    PID_X : PID_BASIC;
    PID_Y : PID_BASIC;

    (* Pulse Shaping Buffers *)
    Pulse_Profile_LUT : ARRAY[0..99] OF LREAL := [100(1.0)]; (* Flat-top default profile *)
    LUT_Index : INT := 0;
END_VAR

(* ----------------------------------------------------------------------------- *)
(* 1. HARDWARE ABSTRACTION & SAFETY INTERLOCKS (KLYSTRON RF)                     *)
(* ----------------------------------------------------------------------------- *)

(* Calculate Voltage Standing Wave Ratio (VSWR) equivalent to detect load mismatch *)
IF Klystron_Fwd_Pwr > 0.0 THEN
    VSWR_Ratio := Klystron_Refl_Pwr / Klystron_Fwd_Pwr;
ELSE
    VSWR_Ratio := 0.0;
END_IF;

(* Fast-acting reflected power interlock (VSWR > 10% for 20ms) *)
TMR_Reflect_Fault(IN := (VSWR_Ratio > 0.10), PT := T#20MS);

(* Thermal overload interlock (Temp > 85C for 100ms) *)
TMR_Thermal_Fault(IN := (Klystron_Temp > 85.0), PT := T#100MS);

(* Evaluate Interlocks *)
IF TMR_Reflect_Fault.Q THEN
    System_State := STATE_FAULT;
    Error_Code := 16#F001; (* RF Reflection Mismatch *)
ELSIF TMR_Thermal_Fault.Q THEN
    System_State := STATE_FAULT;
    Error_Code := 16#F002; (* Thermal Overload *)
ELSIF (System_State = STATE_ACTIVE) AND (BPM_Intensity < 0.1) THEN
    System_State := STATE_FAULT;
    Error_Code := 16#F003; (* Loss of Beam Intensity *)
END_IF;

(* ----------------------------------------------------------------------------- *)
(* 2. STATE MACHINE LOGIC                                                        *)
(* ----------------------------------------------------------------------------- *)
CASE System_State OF

    0: (* STATE_STANDBY *)
        Klystron_Enable := FALSE;
        Beam_Dump_Trig := TRUE; (* Dump active to prevent rogue injection *)
        Quad_X_PWM := 0.0;
        Quad_Y_PWM := 0.0;
        Status_Word := 16#0000;

        IF Enable_Beam AND (Error_Code = 0) THEN
            System_State := STATE_CHARGING;
        END_IF;

    10: (* STATE_CHARGING *)
        Status_Word := 16#0001;
        Beam_Dump_Trig := FALSE; 
        Klystron_Enable := TRUE; (* Enable low-level RF *)
        System_State := STATE_RF_WARMUP;

    20: (* STATE_RF_WARMUP *)
        Status_Word := 16#0002;
        (* Wait for Klystron forward power to stabilize for beam loading *)
        IF Klystron_Fwd_Pwr > 1500.0 THEN (* 1.5 MW nominal *)
            System_State := STATE_ACTIVE;
        END_IF;

    30: (* STATE_ACTIVE - STEERING CONTROL *)
        Status_Word := 16#000F;

        (* Ultra-fast BPM feedback loop (PID execution) *)
        PID_X(ACTUAL := BPM_X_Pos, SETPOINT := Target_X, KP := 2.5, KI := 1.1, KD := 0.05);
        PID_Y(ACTUAL := BPM_Y_Pos, SETPOINT := Target_Y, KP := 2.5, KI := 1.1, KD := 0.05);

        (* Nano-second Sync: Modulo math to cycle through the 100-point LUT *)
        LUT_Index := DINT_TO_INT(Clock_Pulse_NS MOD 100);

        (* Apply pulse profile to steering magnets for precise beam shaping *)
        Quad_X_PWM := PID_X.OUTPUT * Pulse_Profile_LUT[LUT_Index];
        Quad_Y_PWM := PID_Y.OUTPUT * Pulse_Profile_LUT[LUT_Index];

        IF NOT Enable_Beam THEN
            System_State := STATE_STANDBY;
        END_IF;

    99: (* STATE_FAULT *)
        Status_Word := 16#FFFF;
        Klystron_Enable := FALSE;  (* Drop RF power immediately *)
        Beam_Dump_Trig := TRUE;    (* Fire fast kicker to dump beam *)
        Quad_X_PWM := 0.0;         (* De-energize steering magnets *)
        Quad_Y_PWM := 0.0;

        IF NOT Enable_Beam THEN
            (* Acknowledge fault by dropping enable *)
            System_State := STATE_STANDBY;
            Error_Code := 0;
        END_IF;

ELSE
    System_State := STATE_FAULT;
    Error_Code := 16#FFFF; (* Unknown State Exception *)
END_CASE;
END_FUNCTION_BLOCK
