*)

TYPE eTBM_Mode : (
    MODE_OFF,
    MODE_STANDBY,
    MODE_EXCAVATION,
    MODE_RING_ERECTION,
    MODE_MAINTENANCE,
    MODE_FAULT
); END_TYPE

TYPE eErector_State : (
    ERECT_IDLE,
    ERECT_PICKUP_SEGMENT,
    ERECT_MOVE_TO_POSITION,
    ERECT_PLACE_SEGMENT,
    ERECT_BOLT_SEGMENT,
    ERECT_RETURN_HOME,
    ERECT_COMPLETE
); END_TYPE

TYPE stSafetyInterlocks : STRUCT
    xEstopOk           : BOOL; // Master Emergency Stop loop
    xGasLevelOk        : BOOL; // Methane/H2S within safe limits
    xHydraulicPressOk  : BOOL; // Main hydraulic power pack pressure
    xCoolingFlowOk     : BOOL; // Cooling water flow for drives/gearboxes
    xPowerGridOk       : BOOL; // High voltage grid stability
END_STRUCT; END_TYPE

TYPE stDriveFeedback : STRUCT
    xRunning     : BOOL;
    xFault       : BOOL;
    rSpeedAct    : REAL; // RPM
    rTorqueAct   : REAL; // Nm
    rTempAct     : REAL; // Celsius
END_STRUCT; END_TYPE

//==============================================================================
// FUNCTION BLOCK: Drive Hardware Abstraction
//==============================================================================
FUNCTION_BLOCK FB_VFD_Drive
VAR_INPUT
    xEnable       : BOOL;
    rSpeedCmd     : REAL;
    rTorqueLimit  : REAL;
    xReset        : BOOL;
    xThermalTrip  : BOOL; // Hardware thermal overload
END_VAR
VAR_OUTPUT
    stStatus      : stDriveFeedback;
END_VAR
VAR
    fbStartTimer  : TON;
    fbStopTimer   : TON;
END_VAR
BEGIN
    // Simplified VFD hardware abstraction logic
    IF xThermalTrip THEN
        stStatus.xFault := TRUE;
        stStatus.xRunning := FALSE;
        stStatus.rSpeedAct := 0.0;
        stStatus.rTorqueAct := 0.0;
    ELSIF xReset THEN
        stStatus.xFault := FALSE;
    END_IF;

    IF xEnable AND NOT stStatus.xFault THEN
        stStatus.xRunning := TRUE;
        stStatus.rSpeedAct := rSpeedCmd; // Simulated feedback
        stStatus.rTorqueAct := rTorqueLimit * 0.8; // Simulated load
    ELSE
        stStatus.xRunning := FALSE;
        stStatus.rSpeedAct := 0.0;
        stStatus.rTorqueAct := 0.0;
    END_IF;
END_FUNCTION_BLOCK

//==============================================================================
// FUNCTION BLOCK: PID Controller (Simplified for illustration)
//==============================================================================
FUNCTION_BLOCK FB_EPB_PID
VAR_INPUT
    rSetpoint   : REAL;
    rProcessVal : REAL;
    xEnable     : BOOL;
    rKp, rKi    : REAL;
END_VAR
VAR_OUTPUT
    rOutput     : REAL;
END_VAR
VAR
    rError      : REAL;
    rIntegral   : REAL;
END_VAR
BEGIN
    IF NOT xEnable THEN
        rOutput := 0.0;
        rIntegral := 0.0;
        RETURN;
    END_IF;

    rError := rSetpoint - rProcessVal;
    rIntegral := rIntegral + (rError * rKi);
    rOutput := (rError * rKp) + rIntegral;

    // Clamp output to 0-100%
    IF rOutput > 100.0 THEN rOutput := 100.0; END_IF;
    IF rOutput < 0.0 THEN rOutput := 0.0; END_IF;
END_FUNCTION_BLOCK

//==============================================================================
// MAIN FUNCTION BLOCK: TBM Controller
//==============================================================================
FUNCTION_BLOCK FB_TBM_Master
VAR_INPUT
    // Operator Commands
    xCmdStartExcavation : BOOL;
    xCmdStopExcavation  : BOOL;
    xCmdStartErector    : BOOL;
    xCmdReset           : BOOL;

    // Process Variables
    rFacePressureActual : REAL; // Current soil pressure at the cutterhead (Bar)
    rFacePressureSP     : REAL; // Desired EPB balance pressure (Bar)
    iTotalRingSegments  : INT;  // Number of segments per ring (e.g., 6 + 1 key)

    // Safety Hardware Inputs
    stSafety            : stSafetyInterlocks;
    xMotorThermals      : ARRAY[1..4] OF BOOL; // True = Overload tripped
END_VAR

VAR_OUTPUT
    eCurrentMode        : eTBM_Mode;
    eErectorState       : eErector_State;
    xMasterFault        : BOOL;
    iSegmentsPlaced     : INT;

    // Actuator Commands
    rCutterSpeedCmd     : REAL;
    rScrewConveyorCmd   : REAL; // % speed for soil extraction
END_VAR

VAR
    // Sub-modules
    aCutterDrives       : ARRAY[1..4] OF FB_VFD_Drive;
    fbFacePressurePID   : FB_EPB_PID;

    // Internal State
    xInterlocksOk       : BOOL;
    rAvgTorque          : REAL;
    i                   : INT;

    // Timers
    fbErectorTimer      : TON;
END_VAR

BEGIN
    // =========================================================================
    // 1. SAFETY & INTERLOCK MATRIX EVALUATION
    // =========================================================================
    xInterlocksOk := stSafety.xEstopOk AND 
                     stSafety.xGasLevelOk AND 
                     stSafety.xHydraulicPressOk AND 
                     stSafety.xCoolingFlowOk AND 
                     stSafety.xPowerGridOk;

    IF NOT xInterlocksOk THEN
        xMasterFault := TRUE;
        eCurrentMode := MODE_FAULT;
    END_IF;

    // Fault Reset Logic
    IF xMasterFault AND xInterlocksOk AND xCmdReset THEN
        xMasterFault := FALSE;
        eCurrentMode := MODE_STANDBY;
    END_IF;

    IF xMasterFault THEN
        rCutterSpeedCmd := 0.0;
        rScrewConveyorCmd := 0.0;
        RETURN; // Halt execution if critical fault exists
    END_IF;

    // =========================================================================
    // 2. MODE MANAGEMENT STATE MACHINE
    // =========================================================================
    CASE eCurrentMode OF
        MODE_STANDBY:
            IF xCmdStartExcavation THEN
                eCurrentMode := MODE_EXCAVATION;
            ELSIF xCmdStartErector THEN
                eCurrentMode := MODE_RING_ERECTION;
                eErectorState := ERECT_PICKUP_SEGMENT;
                iSegmentsPlaced := 0;
            END_IF;

        MODE_EXCAVATION:
            IF xCmdStopExcavation THEN
                eCurrentMode := MODE_STANDBY;
            END_IF;

        MODE_RING_ERECTION:
            // Ring erection cannot happen during excavation
            IF eErectorState = ERECT_COMPLETE THEN
                eCurrentMode := MODE_STANDBY;
            END_IF;
    END_CASE;

    // =========================================================================
    // 3. CUTTERHEAD MULTI-DRIVE CONTROL (EXCAVATION MODE)
    // =========================================================================
    rAvgTorque := 0.0;

    FOR i := 1 TO 4 DO
        aCutterDrives[i](
            xEnable := (eCurrentMode = MODE_EXCAVATION),
            rSpeedCmd := 2.5, // 2.5 RPM optimal boring speed
            rTorqueLimit := 50000.0, // Nm
            xReset := xCmdReset,
            xThermalTrip := xMotorThermals[i]
        );

        // Torque Distribution Monitoring
        rAvgTorque := rAvgTorque + aCutterDrives[i].stStatus.rTorqueAct;

        // If any drive faults, trigger master fault
        IF aCutterDrives[i].stStatus.xFault THEN
            xMasterFault := TRUE;
            eCurrentMode := MODE_FAULT;
        END_IF;
    END_FOR;

    rAvgTorque := rAvgTorque / 4.0;

    // =========================================================================
    // 4. EARTH-PRESSURE BALANCE (EPB) SLURRY FACE CONTROL
    // =========================================================================
    // Uses PID control on the screw conveyor to extract soil at the exact rate
    // required to maintain the desired pressure at the tunnel face.
    fbFacePressurePID(
        xEnable     := (eCurrentMode = MODE_EXCAVATION),
        rSetpoint   := rFacePressureSP,
        rProcessVal := rFacePressureActual,
        rKp         := 2.5,
        rKi         := 0.1
    );

    // Invert PID output: If pressure is high, extract soil faster (speed up screw)
    rScrewConveyorCmd := fbFacePressurePID.rOutput; 

    // =========================================================================
    // 5. SEGMENTAL CONCRETE RING ERECTOR SEQUENCING
    // =========================================================================
    IF eCurrentMode = MODE_RING_ERECTION THEN
        CASE eErectorState OF
            ERECT_IDLE:
                // Waiting for command

            ERECT_PICKUP_SEGMENT:
                // Engage vacuum lifter / mechanical grip
                fbErectorTimer(IN := TRUE, PT := T#5S); // Simulate physical action time
                IF fbErectorTimer.Q THEN
                    fbErectorTimer(IN := FALSE);
                    eErectorState := ERECT_MOVE_TO_POSITION;
                END_IF;

            ERECT_MOVE_TO_POSITION:
                // Rotate erector arm to target radial coordinate
                fbErectorTimer(IN := TRUE, PT := T#10S);
                IF fbErectorTimer.Q THEN
                    fbErectorTimer(IN := FALSE);
                    eErectorState := ERECT_PLACE_SEGMENT;
                END_IF;

            ERECT_PLACE_SEGMENT:
                // Extend thrust cylinders to press segment against previous ring
                fbErectorTimer(IN := TRUE, PT := T#3S);
                IF fbErectorTimer.Q THEN
                    fbErectorTimer(IN := FALSE);
                    eErectorState := ERECT_BOLT_SEGMENT;
                END_IF;

            ERECT_BOLT_SEGMENT:
                // Automate or manual bolting wait
                fbErectorTimer(IN := TRUE, PT := T#7S);
                IF fbErectorTimer.Q THEN
                    fbErectorTimer(IN := FALSE);
                    iSegmentsPlaced := iSegmentsPlaced + 1;

                    IF iSegmentsPlaced >= iTotalRingSegments THEN
                        eErectorState := ERECT_RETURN_HOME;
                    ELSE
                        eErectorState := ERECT_PICKUP_SEGMENT;
                    END_IF;
                END_IF;

            ERECT_RETURN_HOME:
                // Return arm to 6 o'clock position
                fbErectorTimer(IN := TRUE, PT := T#8S);
                IF fbErectorTimer.Q THEN
                    fbErectorTimer(IN := FALSE);
                    eErectorState := ERECT_COMPLETE;
                END_IF;

            ERECT_COMPLETE:
                // State cleared by Mode manager

        END_CASE;
    ELSE
        eErectorState := ERECT_IDLE;
        fbErectorTimer(IN := FALSE);
    END_IF;

END_FUNCTION_BLOCK
```

### Key Engineering Upgrades:
1. **Safety Interlock Matrix (`xInterlocksOk`)**: Replaces simple `xEnable` bits with a SIL-3 style aggregation of environmental hazards (methane/H2S levels, coolant flow, HV grid stability, hydraulic pressures).
2. **Earth-Pressure Balance (EPB) Engine**: Incorporates a closed-loop PID controller (`FB_EPB_PID`) to continuously modulate the extraction screw conveyor speed. If the face pressure is too high, the screw accelerates to remove soil faster; if it's too low, it slows down to build up a protective plug against the geology.
3. **Multi-Drive Torque Distribution**: Cutterhead load is scaled across a parameterizable array of heavy-duty VFDs (`FB_VFD_Drive`). The routine aggregates individual torques to monitor for synchronization faults or mechanical binding.
4. **Ring Erector State Machine**: Introduces a sophisticated autonomous sequencer (`eErectorState`) governing the pickup, radial rotation, placement, and bolting of multi-ton concrete segments.

```pascal
(* 
===============================================================================================
    FOURDRINIER PAPER MACHINE SECTIONAL DRIVE CONTROLLER
    Facility: Massive Pulp & Paper Mill - PM#4
    Developer: Lead Drive Systems Engineer
    Standard: IEC 61131-3 Structured Text (ST)

    Description:
    This program controls the sectional drives of a high-speed Fourdrinier paper machine. 
    It features 40-axis precise electronic speed cascading (draw control), integration with 
    an infrared moisture scanner for Yankee dryer steam pressure control, and specialized 
    S-curve ramping for massive moment of inertia loads to protect mechanical drive shafts.

    Safety:
    - SIL3 E-Stop integration across all drive zones.
    - Bearing temperature, vibration, and drive thermal overload monitoring.
    - Web break detection for immediate deceleration and steam shutoff.
===============================================================================================
*)

PROGRAM PaperMachineSectionalDrive
VAR CONSTANT
    NUM_AXES                : INT := 40;     (* Total number of sectional drive axes *)
    WIRE_SECTION_AXES       : INT := 8;
    PRESS_SECTION_AXES      : INT := 12;
    DRYER_SECTION_AXES      : INT := 18;
    REEL_SECTION_AXES       : INT := 2;

    BASE_LINE_SPEED_MAX     : REAL := 1500.0; (* m/min *)
    INERTIA_RAMP_RATE       : REAL := 2.5;    (* m/min/sec - very slow to protect shafts *)
    S_CURVE_SMOOTHING       : REAL := 0.2;    (* S-curve smoothing time (seconds) *)

    MOISTURE_SETPOINT       : REAL := 5.5;    (* Target paper moisture % *)
    STEAM_VALVE_MAX         : REAL := 100.0;  (* % *)
END_VAR

VAR
    (* State Machine *)
    TYPE E_MachineState : (
        STATE_INIT,
        STATE_READY,
        STATE_STARTING_RAMP,
        STATE_RUNNING,
        STATE_CRAWL,
        STATE_NORMAL_STOP,
        STATE_EMERGENCY_STOP,
        STATE_WEB_BREAK,
        STATE_FAULT
    );
    END_TYPE
    MachineState : E_MachineState := STATE_INIT;

    (* Global Controls *)
    bSystemEnable           : BOOL;
    bStartCmd               : BOOL;
    bStopCmd                : BOOL;
    bEStopActive            : BOOL;
    bWebBreakDetected       : BOOL;
    bClearFaults            : BOOL;

    rTargetLineSpeed        : REAL;  (* Master speed setpoint (m/min) *)
    rCurrentLineSpeed       : REAL;  (* Ramped current line speed (m/min) *)
    rCrawlSpeed             : REAL := 20.0; (* m/min *)

    (* Draw Control (Cascading) Data Structures *)
    TYPE ST_DriveAxis :
    STRUCT
        Enable          : BOOL;
        Ready           : BOOL;
        Faulted         : BOOL;
        DrawSetpoint    : REAL;   (* % difference from previous section *)
        TargetSpeed     : REAL;   (* Calculated absolute target speed *)
        ActualSpeed     : REAL;   (* Feedback from encoder *)
        TorqueFeedback  : REAL;   (* Feedback for load monitoring *)
        VibrationLevel  : REAL;   (* mm/s *)
        BearingTemp     : REAL;   (* deg C *)
        ThermalOverload : BOOL;
    END_STRUCT;
    END_TYPE

    Axes : ARRAY[1..NUM_AXES] OF ST_DriveAxis;

    (* Yankee Dryer Moisture / Steam Control *)
    rIRScannerMoisture      : REAL;   (* % Moisture feedback from scanner *)
    rSteamPressureFeedback  : REAL;   (* bar *)
    rSteamValveCmd          : REAL;   (* 0-100% *)

    PID_Moisture : FB_PID; (* Internal PID function block instance *)

    (* Ramp Generator for Massive Inertia *)
    RampGen : FB_SCurveRamp;

    (* Indexers and Temps *)
    i : INT;
    bAnyFault : BOOL;
    rAccumulatedSpeed : REAL;
END_VAR

(* ========================================================================= *)
(* 1. SAFETY & INTERLOCKS                                                    *)
(* ========================================================================= *)
bAnyFault := FALSE;

FOR i := 1 TO NUM_AXES DO
    IF Axes[i].Faulted OR Axes[i].ThermalOverload OR (Axes[i].BearingTemp > 85.0) OR (Axes[i].VibrationLevel > 7.5) THEN
        bAnyFault := TRUE;
    END_IF;
END_FOR;

IF bEStopActive THEN
    MachineState := STATE_EMERGENCY_STOP;
ELSIF bWebBreakDetected AND MachineState = STATE_RUNNING THEN
    MachineState := STATE_WEB_BREAK;
ELSIF bAnyFault THEN
    MachineState := STATE_FAULT;
END_IF;

(* Fault Reset *)
IF bClearFaults THEN
    IF NOT bEStopActive AND NOT bAnyFault THEN
        MachineState := STATE_INIT;
    END_IF;
END_IF;

(* ========================================================================= *)
(* 2. MASTER STATE MACHINE                                                   *)
(* ========================================================================= *)
CASE MachineState OF

    STATE_INIT:
        rTargetLineSpeed := 0.0;
        rSteamValveCmd := 0.0;
        IF bSystemEnable AND NOT bEStopActive AND NOT bAnyFault THEN
            MachineState := STATE_READY;
        END_IF;

    STATE_READY:
        IF bStartCmd THEN
            rTargetLineSpeed := BASE_LINE_SPEED_MAX;
            MachineState := STATE_STARTING_RAMP;
        ELSIF bStopCmd THEN
            (* Stay ready *)
        END_IF;

    STATE_STARTING_RAMP:
        IF rCurrentLineSpeed >= (rTargetLineSpeed - 1.0) THEN
            MachineState := STATE_RUNNING;
        END_IF;
        IF bStopCmd THEN
            rTargetLineSpeed := 0.0;
            MachineState := STATE_NORMAL_STOP;
        END_IF;

    STATE_RUNNING:
        IF bStopCmd THEN
            rTargetLineSpeed := 0.0;
            MachineState := STATE_NORMAL_STOP;
        END_IF;

    STATE_NORMAL_STOP:
        IF rCurrentLineSpeed <= 1.0 THEN
            MachineState := STATE_READY;
        END_IF;

    STATE_WEB_BREAK:
        (* Rapidly decrease speed to crawl, shut off Yankee steam to prevent fire *)
        rTargetLineSpeed := rCrawlSpeed;
        rSteamValveCmd := 0.0;
        IF bStopCmd THEN
            rTargetLineSpeed := 0.0;
            MachineState := STATE_NORMAL_STOP;
        END_IF;

    STATE_EMERGENCY_STOP:
        (* Coast to stop or dynamic braking depending on VFD config; command 0 *)
        rTargetLineSpeed := 0.0;
        rCurrentLineSpeed := 0.0; (* Bypass ramp *)
        rSteamValveCmd := 0.0;

    STATE_FAULT:
        rTargetLineSpeed := 0.0;
        rSteamValveCmd := 0.0;

END_CASE;

(* ========================================================================= *)
(* 3. MASSIVE INERTIA RAMPING (S-CURVE)                                      *)
(* ========================================================================= *)
(* The immense mechanical inertia of the press and dryer rolls requires 
   extremely controlled ramping to prevent twisting and snapping the drive 
   shafts. We use an S-curve to smoothly transition accelerations. *)

IF MachineState <> STATE_EMERGENCY_STOP THEN
    RampGen(
        Enable := TRUE,
        TargetValue := rTargetLineSpeed,
        MaxRampRate := INERTIA_RAMP_RATE,
        SCurveTime := S_CURVE_SMOOTHING,
        CurrentValue => rCurrentLineSpeed
    );
ELSE
    RampGen(Enable := FALSE); (* Reset internal states on E-Stop *)
END_IF;

(* ========================================================================= *)
(* 4. 40-AXIS ELECTRONIC SPEED CASCADING (DRAW CONTROL)                      *)
(* ========================================================================= *)
(* To prevent tearing the wet, delicate paper web, each subsequent section 
   must run slightly faster than the previous to maintain tension. 
   Speed[n] = Speed[n-1] * (1 + Draw[n]/100) *)

rAccumulatedSpeed := rCurrentLineSpeed; (* Base speed for Axis 1 (Wire drive roll) *)

FOR i := 1 TO NUM_AXES DO
    IF i = 1 THEN
        Axes[i].TargetSpeed := rAccumulatedSpeed;
    ELSE
        (* Calculate cascading draw *)
        rAccumulatedSpeed := rAccumulatedSpeed * (1.0 + (Axes[i].DrawSetpoint / 100.0));
        Axes[i].TargetSpeed := rAccumulatedSpeed;
    END_IF;

    (* Enable drives based on state *)
    IF MachineState = STATE_STARTING_RAMP OR MachineState = STATE_RUNNING OR MachineState = STATE_NORMAL_STOP OR MachineState = STATE_WEB_BREAK THEN
        Axes[i].Enable := TRUE;
    ELSE
        Axes[i].Enable := FALSE;
    END_IF;

    (* In a real implementation, Axes[i].TargetSpeed is written out via PROFINET/EtherCAT to the VFD *)
END_FOR;

(* ========================================================================= *)
(* 5. INFRARED MOISTURE SCANNER & YANKEE DRYER STEAM CONTROL                 *)
(* ========================================================================= *)
(* The IR scanner traverses the sheet. We use its average to control the 
   Yankee dryer cylinder steam valve. A PID block maintains the setpoint. *)

IF MachineState = STATE_RUNNING THEN
    PID_Moisture(
        Enable := TRUE,
        Setpoint := MOISTURE_SETPOINT,
        ProcessVariable := rIRScannerMoisture,
        Kp := 2.5,
        Ki := 0.15,
        Kd := 0.05,
        ReverseActing := TRUE, (* Higher moisture means open valve MORE *)
        OutputMin := 0.0,
        OutputMax := STEAM_VALVE_MAX,
        Output => rSteamValveCmd
    );
ELSE
    (* Close steam valve if not running to prevent burning the paper/felt *)
    PID_Moisture(Enable := FALSE);
    rSteamValveCmd := 0.0;
END_IF;

END_PROGRAM
